// gate worker — M6 spec §6：WS↔TCP 隧道桥（TLS 端到端透传，Worker 只见密文）
// 安全：Bearer(sha256(tunnel_token)) 强制；ACL 仅 443（80 默认禁用）；
//       私网/CF 字面量拒绝主防线为 workerd 平台层解析后 IP 强制（spec §7 声明）。
import { connect } from 'cloudflare:sockets'

const ALLOWED_PORTS = new Set([443]) // 80 明文透传默认禁用（M6 spec R8/F12）
const MAX_NAME_LEN = 253

function sha256Hex(s) {
  // Workers 无同步 crypto；用异步子流程在鉴权处 await
  return crypto.subtle.digest('SHA-256', new TextEncoder().encode(s)).then(b =>
    [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('')
  )
}

function validHost(h) {
  if (!h || typeof h !== 'string' || h.length > MAX_NAME_LEN) return false
  const lower = h.toLowerCase()
  if (lower === 'localhost' || lower.endsWith('.localhost')) return false
  if (/^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(lower)) return false
  if (/^0177\.|^0x7f\.|^\[?::1\]?$/.test(lower)) return false // 八进制/十六进制/IPv6 回环变体
  return true
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url)
    if (url.pathname === '/debug') {
      const v = env.TUNNEL_TOKEN_HASH
      return new Response(JSON.stringify({ set: typeof v === 'string', len: typeof v === 'string' ? v.length : 0 }), { headers: { 'content-type': 'application/json' } })
    }
    if (url.pathname !== '/ws') return new Response('not found', { status: 404 })
    if (request.headers.get('Upgrade')?.toLowerCase() !== 'websocket') {
      return new Response('websocket required', { status: 400 })
    }
    // 鉴权：恒时比较 sha256(Bearer token) vs env.TUNNEL_TOKEN_HASH
    const auth = request.headers.get('Authorization') ?? ''
    const presented = auth.startsWith('Bearer ') ? auth.slice(7) : ''
    const hash = await sha256Hex(presented)
    if (!presented || hash !== env.TUNNEL_TOKEN_HASH) {
      return new Response('unauthorized', { status: 401 })
    }

    const pair = new WebSocketPair()
    const server = pair[1]
    server.accept()

    let sock = null
    let established = false

    server.addEventListener('message', async (event) => {
      if (established) {
        // 数据帧：写向已建立的 TCP（文本帧在此阶段视为协议错误，忽略）
        if (event.data instanceof ArrayBuffer) sock.write(new Uint8Array(event.data))
        return
      }
      // 首帧：JSON {"host","port"}
      let req
      try {
        req = JSON.parse(event.data)
      } catch {
        server.close(1008, 'bad first frame'); return
      }
      const port = Number(req.port)
      if (!validHost(req.host) || !ALLOWED_PORTS.has(port)) {
        server.send(JSON.stringify({ ok: false, reason: 'acl denied' }))
        server.close(1008, 'acl'); return
      }
      try {
        sock = connect({ hostname: req.host, port })
        const closed = new Promise((res) => sock.closed.then(res).catch(res))
        sock.opened.then(() => {
          established = true
          server.send(JSON.stringify({ ok: true }))
        }).catch((e) => {
          server.send(JSON.stringify({ ok: false, reason: String(e) }))
          server.close(1011, 'connect failed')
        })
        // TCP→WS 方向
        ;(async () => {
          try {
            for await (const chunk of sock.readable) {
              if (server.readyState === 1) server.send(chunk)
            }
          } catch { /* 连接中断由 close 处理 */ }
          try { server.close(1000, 'upstream closed') } catch {}
        })()
        await closed
      } catch (e) {
        server.send(JSON.stringify({ ok: false, reason: String(e) }))
        try { server.close(1011, 'connect error') } catch {}
      }
    })

    server.addEventListener('close', () => { try { sock?.close() } catch {} })

    return new Response(null, { status: 101, webSocket: server })
  },
}
